public sealed record Move
{
    public required Position From { get; init; }
    public required Position To { get; init; }
    public required IReadOnlyList<Position> Path { get; init; }
    public required IReadOnlyList<Position> CapturedPositions { get; init; }
    public bool IsPromotion { get; init; }
    public bool IsCapture => CapturedPositions.Count > 0;
    public string Notation { get; init; } = string.Empty;
}

private void OrderBitMoves(
    Span<BitMove> moves,
    ushort ttPackedMove,
    bool hasTtMove,
    int ply,
    PieceColor sideToMove)
{
    int count = moves.Length;
    if (count <= 1)
        return;

    Span<int> scores = stackalloc int[count];
    ushort killer1 = 0;
    ushort killer2 = 0;
    if ((uint)ply < MaxPly)
    {
        int killerIdx = ply << 1;
        killer1 = _killers[killerIdx];
        killer2 = _killers[killerIdx + 1];
    }
    int sideOffset = (int)sideToMove << 12;

    for (int i = 0; i < count; i++)
    {
        ref readonly BitMove m = ref moves[i];
        ushort packed = m.PackedMove;
        int score;
        if (hasTtMove && packed == ttPackedMove)
        {
            score = 10_000_000;
        }
        else if (m.IsCapture)
        {
            score = 1_000_000 + (m.CaptureCount * 10_000) + (m.IsPromotion ? 1_000 : 0);
        }
        else if (m.IsPromotion)
        {
            score = 500_000;
        }
        else if (packed == killer1)
        {
            score = 90_000;
        }
        else if (packed == killer2)
        {
            score = 80_000;
        }
        else
        {
            score = _history[sideOffset | (m.From << 6) | m.To];
        }
        scores[i] = score;
    }

    for (int i = 1; i < count; i++)
    {
        int currentScore = scores[i];
        if (currentScore == 0)
            continue;

        BitMove currentMove = moves[i];
        int j = i - 1;
        while (j >= 0 && scores[j] < currentScore)
        {
            moves[j + 1] = moves[j];
            scores[j + 1] = scores[j];
            j--;
        }
        moves[j + 1] = currentMove;
        scores[j + 1] = currentScore;
    }
}

[MethodImpl(MethodImplOptions.AggressiveInlining)]
public unsafe void Prefetch(ulong key)
{
    if (Sse.IsSupported)
    {
        ref TranspositionEntry bucket0 = ref Unsafe.Add(
            ref MemoryMarshal.GetArrayDataReference(_entries),
            (int)(key & _bucketMask) << 2);
        Sse.Prefetch0(Unsafe.AsPointer(ref bucket0));
    }
}

